import os

os.chdir(r"C:\Users\quack\Desktop\Iron\.claude\worktrees\recursing-wright-856ffa\tools\platypus_ts_tests")
NL = "\\n"  # a backslash and n inside the generated TypeScript string literals
out = '''// Intl step I4: PluralRules, ListFormat, RelativeTimeFormat. Every exported function without
// parameters returns a string; `gen_intl4_expected.ts` runs this file in bun. Generated by
// bench/gen_intl4_program.py (the option sets are written out because Platypus reads them as literals).

function fail(f: () => string): string {
  try {
    return f();
  } catch (e) {
    return (e as Error).name + ": " + (e as Error).message;
  }
}

const NUMS = [0, 1, 2, 3, 4, 5, 6, 7, 10, 11, 12, 13, 14, 20, 21, 22, 25, 100, 101, 102, 111, 1000, 1000000, 0.5, 1.5, 2.5, -1, -2];

'''
plural_locs = ["en", "ar", "ru", "pl", "fr", "ja", "cy", "he", "lt", "ga", "es", "de", "cs", "sl", "uk", "pt", "it", "hi", "tr", "ko"]
out += 'export function pluralCardinal(): string {\n  let out = "";\n'
for l in plural_locs:
    out += f'  out += "{l}:" + NUMS.map((n) => new Intl.PluralRules("{l}").select(n)).join(",") + "{NL}";\n'
out += "  return out;\n}\n\n"
out += 'export function pluralOrdinal(): string {\n  let out = "";\n'
for l in ["en", "sv", "fr", "it", "cy", "hu", "ro", "ja"]:
    out += f'  out += "{l}:" + NUMS.map((n) => new Intl.PluralRules("{l}", {{ type: "ordinal" }}).select(n)).join(",") + "{NL}";\n'
out += "  return out;\n}\n\n"
out += '''export function pluralFraction(): string {
  const a = new Intl.PluralRules("en", { minimumFractionDigits: 1 });
  const b = new Intl.PluralRules("en", { maximumFractionDigits: 0 });
  const c = new Intl.PluralRules("fr", { minimumFractionDigits: 2 });
  return [1, 1.0, 2, 1.5, 0.99, 1.4].map((n) => a.select(n) + "/" + b.select(n) + "/" + c.select(n)).join(",") + "|" + new Intl.PluralRules("en").select(NaN) + new Intl.PluralRules("en").select(Infinity);
}

export function pluralErrors(): string {
  return [
    fail(() => new Intl.PluralRules("en", { type: "x" as any }).select(1)),
    fail(() => new Intl.PluralRules("bad tag!").select(1)),
  ].join("NLTOKEN");
}

'''.replace("NLTOKEN", NL)
lists = [[], ["a"], ["a", "b"], ["a", "b", "c"], ["a", "b", "c", "d"]]


def arr(l):
    return "[" + ", ".join(f'"{x}"' for x in l) + "]"


locs = ["en", "en-GB", "de", "fr", "es", "it", "pt", "nl", "sv", "ru", "pl", "ja", "ko", "zh", "ar", "hi", "tr"]
for typ in ["conjunction", "disjunction", "unit"]:
    out += f'export function list_{typ}(): string {{\n  let out = "";\n'
    for l in locs:
        for style in ["long", "short", "narrow"]:
            calls = ", ".join("f.format(" + arr(x) + ")" for x in lists)
            out += f'  {{\n    const f = new Intl.ListFormat("{l}", {{ type: "{typ}", style: "{style}" }});\n    out += "{l}/{style}:" + [{calls}].join(" | ") + "{NL}";\n  }}\n'
    out += "  return out;\n}\n\n"
out += '''export function listDefaults(): string {
  return [new Intl.ListFormat("en").format(["a", "b", "c"]), new Intl.ListFormat("de").format(["x", "y"]), new Intl.ListFormat("en", { style: "short" }).format(["p", "q", "r"])].join("|");
}

export function listErrors(): string {
  return [
    fail(() => new Intl.ListFormat("en", { style: "x" as any }).format(["a"])),
    fail(() => new Intl.ListFormat("en", { type: "x" as any }).format(["a"])),
    fail(() => new Intl.ListFormat("bad tag!").format(["a"])),
  ].join("NLTOKEN");
}

'''.replace("NLTOKEN", NL)
units = ["second", "minute", "hour", "day", "week", "month", "quarter", "year"]
vals = [-3, -1, 0, 1, 2, 5, 1.5, -0.5, 100]
rt_locs = ["en", "en-GB", "de", "fr", "es", "it", "pt", "nl", "sv", "ru", "pl", "ja", "ko", "zh", "ar", "hi", "tr"]
for numeric in ["always", "auto"]:
    for style in ["long", "short", "narrow"]:
        out += f'export function rtf_{numeric}_{style}(): string {{\n  let out = "";\n'
        for l in rt_locs:
            out += f'  {{\n    const f = new Intl.RelativeTimeFormat("{l}", {{ numeric: "{numeric}", style: "{style}" }});\n'
            out += f'    out += "{l}:";\n'
            for u in units:
                calls = ", ".join(f'f.format({v}, "{u}")' for v in vals)
                out += f'    out += [{calls}].join(" | ") + " ; ";\n'
            out += f'    out += "{NL}";\n  }}\n'
        out += "  return out;\n}\n\n"
out += '''export function rtfPluralUnits(): string {
  const f = new Intl.RelativeTimeFormat("en");
  return [f.format(1, "days"), f.format(-5, "hours"), f.format(2, "years"), f.format(1, "quarters"), f.format(0, "seconds"), f.format(-0, "second")].join("|");
}

export function rtfErrors(): string {
  const f = new Intl.RelativeTimeFormat("en");
  return [
    fail(() => f.format(1, "fortnight")),
    fail(() => f.format(NaN, "day")),
    fail(() => f.format(Infinity, "day")),
    fail(() => new Intl.RelativeTimeFormat("en", { numeric: "x" as any }).format(1, "day")),
    fail(() => new Intl.RelativeTimeFormat("en", { style: "x" as any }).format(1, "day")),
    fail(() => new Intl.RelativeTimeFormat("bad tag!").format(1, "day")),
  ].join("NLTOKEN");
}
'''.replace("NLTOKEN", NL)
open("bench/intl4.ts", "w", encoding="utf8", newline="").write(out)
print(len(out))
